class PrefixCode:
    def __init__(self):
        self.root = [None, None]

    def add_msb(self, sym, code, length):
        node = self.root
        for b in range(length - 1, -1, -1):
            bit = (code >> b) & 1
            if b == 0:
                node[bit] = sym
            else:
                if node[bit] is None:
                    node[bit] = [None, None]
                node = node[bit]

    def add_lsb(self, sym, code, length):
        node = self.root
        for b in range(length):
            bit = (code >> b) & 1
            if b == length - 1:
                node[bit] = sym
            else:
                if node[bit] is None:
                    node[bit] = [None, None]
                node = node[bit]

    @staticmethod
    def from_lengths(lengths):
        pc = PrefixCode()
        max_len = max((l for l in lengths if l > 0), default=0)
        code = 0
        for bl in range(1, max_len + 1):
            for sym, l in enumerate(lengths):
                if l == bl:
                    pc.add_msb(sym, code, bl)
                    code += 1
            code <<= 1
        return pc


class BitReaderLE:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos
        self.buf = 0
        self.bits = 0

    def read_bit(self):
        if self.bits == 0:
            self.buf = self.data[self.pos] if self.pos < len(self.data) else 0
            self.pos += 1
            self.bits = 8
        b = self.buf & 1
        self.buf >>= 1
        self.bits -= 1
        return b

    def read_bits(self, n):
        res = 0
        for i in range(n):
            res |= self.read_bit() << i
        return res

    def read_sym(self, pc):
        node = pc.root
        while isinstance(node, list):
            node = node[self.read_bit()]
            if node is None:
                raise ValueError("Invalid Huffman code")
        return node


def parse_dyn_code(br, numcodes, metacode):
    length = 0
    lengths = [0] * numcodes
    i = 0
    while i < numcodes:
        val = br.read_sym(metacode)
        if val == 31:
            length = -1
        elif val == 32:
            length += 1
        elif val == 33:
            length -= 1
        elif val == 34:
            if br.read_bit():
                lengths[i] = length
                i += 1
        elif val == 35:
            cnt = br.read_bits(3) + 2
            for _ in range(cnt):
                lengths[i] = length
                i += 1
        elif val == 36:
            cnt = br.read_bits(6) + 10
            for _ in range(cnt):
                lengths[i] = length
                i += 1
        else:
            length = val + 1
        if i < numcodes:
            lengths[i] = length
            i += 1
    return PrefixCode.from_lengths(lengths)


